     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
     * normalized telephone concatenated with the last name (the same HASH8 used by the
     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
     *
     * <p>When the computed id collides with an already-registered owner's memberId it is
     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
     */
    private String memberId(Owner owner) {
        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
        String core = region + fy + hash8;
        String base = core + OwnerMapper.luhn(core);
        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
            .map(Owner::getMemberId)
            .filter(java.util.Objects::nonNull)
            .collect(java.util.stream.Collectors.toSet());
        return disambiguate(base, existing);
    }

    /**
     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
     * identity code passes through, so a collision is broken the one way wherever a code is built.
     */
    private static String disambiguate(String base, java.util.Set<String> existing) {
        if (!existing.contains(base)) {
            return base;
        }
        int n = 2;
        while (existing.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * The number of existing owners that share {@code owner}'s firstName and lastName,
     * compared case-insensitively. The candidate is not yet stored at the point this is
     * assigned, so it does not count itself. This is the value stored as the owner's
     * namesakeCount on create.
     */
    private int namesakeCount(Owner owner) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /** Fixed list of public holidays that a registration date must roll past. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    /**
     * Roll a registration date forward to the next business day: a Saturday, Sunday
     * or listed public holiday advances one day at a time until it lands on a weekday
     * that is not a public holiday. A plain weekday is returned unchanged.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isWeekend(LocalDate date) {
        return switch (date.getDayOfWeek()) {
            case SATURDAY, SUNDAY -> true;
            default -> false;
        };
    }
}

